"""Explain killable types, try-consume, observation and completion reuse."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1517': ('같은 “중단” 안내라도 모든 연락에 멈추는 규칙과 긴급 종료 연락에만 멈추는 규칙은 다릅니다. 결과에 같은 중단 번호가 적혀 있어도 어떤 연락을 허용했는지는 따로 봐야 합니다.', 'killable의 신호 규칙과 실제 반환 자료형을 구별합니다.', '시간 제한 없는 killable: int, 성공 0, 중단 -ERESTARTSYS를 적으세요. timeout: long, 양수 성공·0 만료·음수 중단을 그 아래 적으세요.', ['wait_for_completion_killable은 TASK_KILLABLE이라는 대기 상태를 고릅니다. 치명적인 종료 신호에 반응할 수 있는 방식입니다. 일반 interruptible 변형은 TASK_INTERRUPTIBLE을 고르므로 둘이 허용하는 신호 범위를 같은 것으로 외우면 안 됩니다.', '신호는 작업에 보내는 알림입니다. signal_pending_state는 대기 상태에 중단을 허용하는 표시가 있는지, 실제 신호가 있는지, 치명적인 종료 신호인지 등을 봅니다. 함수 이름에 killable이 있다고 임의의 알림이 모두 기다림을 중단시키지는 않습니다.', '시간 제한 없는 killable은 정상 완료면 0을 돌려주고 허용 신호 때문에 중단되면 -ERESTARTSYS를 돌려줍니다. 내부 공통 결과를 long t로 받지만 이 wrapper가 밖으로 돌려주는 실제 형식은 int입니다. 내부 변수와 함수 결과의 형식은 다를 수 있습니다.', '이 고정 버전의 completion.h 선언과 completion.c 정의 모두 int입니다. 문서 예시에서 다른 형식을 보았다면 두 코드 위치를 대조하세요. int와 long은 모두 정수 형식이지만 크기와 호출 규칙을 함부로 같다고 가정할 수 없습니다.', '시간 제한이 있는 wait_for_completion_killable_timeout은 long을 반환합니다. 성공이면 양수, 완료 없이 시간 만료면 0, 허용된 신호로 중단되면 음수입니다. 시간 제한 없는 함수의 0 성공 규칙을 여기에 그대로 적용하면 뜻이 뒤집힙니다.', 'wait_for_completion_state는 호출자가 준 state를 공통 대기에 전달합니다. 항상 killable로 바꾸는 함수가 아닙니다. 선택한 상태가 어떤 신호와 깨움을 허용하는지, 기다려도 되는 상황인지 호출자가 확인해야 합니다. 결과 숫자뿐 아니라 그 결과에 이르는 규칙을 함께 읽으세요.'], [('이 버전에서 시간 제한 없는 wait_for_completion_killable의 실제 반환 형식은?', ['문서 예시만 보고 반드시 long이라고 정해요', '헤더와 정의에 적힌 int예요'], '실제 선언과 정의는 int입니다. 본체의 임시 변수 t가 long이라는 사실과 함수 반환 형식을 구별하세요. timeout 변형은 별도로 long을 반환합니다.'), ('killable과 interruptible은 모든 신호에 똑같이 반응하나요?', ['아니요. 고르는 대기 상태와 허용 신호 규칙이 달라요', '네. 이름만 다르고 상태도 같아요'], '각각 TASK_KILLABLE과 TASK_INTERRUPTIBLE을 선택합니다. 같은 -ERESTARTSYS로 중단을 알리더라도 중단을 허용하는 신호 범위까지 같은 것은 아니에요.')]), 'os1518': ('상자에 도장이 하나 있는 것을 보고 손을 뻗었는데 다른 친구가 먼저 가져갔다고 해 봅시다. 내가 실제로 가져가는 차례가 왔을 때 다시 확인해야 도장이 없는 상태에서 가져갔다고 말하지 않습니다.', '빠른 관측 뒤 잠금 안에서 다시 확인하고 표시를 소비하는 이유를 이해합니다.', 'A가 done=1 확인 → B가 하나 소비해 0 → A가 잠금 잡고 재확인 → false를 적으세요. 아무도 먼저 가져가지 않은 경우와 비교하세요.', ['try_wait_for_completion은 완료 표시를 지금 사용할 수 있는지 시도합니다. 완료를 기다리려고 대기 줄에 등록하거나 schedule로 잠드는 경로가 없습니다. 그렇다고 함수 안에 잠금이 전혀 없는 것은 아닙니다.', '첫 READ_ONCE(done)이 0이면 바로 false를 반환합니다. READ_ONCE는 이 값을 읽는 데 쓰는 커널 도우미입니다. 값을 한 번 관측하는 것만으로 그 값을 내 것으로 예약하거나 다른 작업의 변경을 막지는 않습니다.', '처음 값이 0이 아니면 raw_spin_lock_irqsave로 잠금을 잡고 done을 다시 확인합니다. 첫 확인과 잠금 사이에 다른 대기자가 표시를 써 버릴 수 있어서입니다. A가 1을 보았어도 B가 먼저 소비하여 0이면 A의 두 번째 확인에서는 실패합니다.', '잠금 안에서 done=0이면 결과를 false로 합니다. 보통의 양수가 남아 있으면 하나 줄이고 true를 반환합니다. 예를 들어 2가 남아 있으면 1로 만들고 성공입니다. UINT_MAX라는 특별한 완료 상태이면 줄이지 않고 true입니다.', '마지막에는 잠금을 풀고 이전 인터럽트 상태를 복구합니다. 이 시도는 완료 알림이 올 때까지 잠들어 기다리지 않지만 raw 잠금을 얻기 위한 짧은 경쟁은 있을 수 있습니다. “비차단 소비 검사”를 아무 비용도 없는 무잠금 함수라는 뜻으로 읽지 마세요.', 'false는 이번 관측과 시도에서 표시를 소비하지 못했다는 결과입니다. 직후에 다른 작업이 complete할 수도 있습니다. true 역시 mutex 소유권이나 자료를 바로 없애도 된다는 허가가 아닙니다. 완료 자료와 다른 사용자들의 수명 규칙을 따로 지켜야 합니다.'], [('처음에는 done=1을 봤지만 잠금을 잡았을 때 다른 작업이 소비해 0이에요. 결과는?', ['처음 1을 봤으니 언제나 true예요', '다시 확인한 0에 따라 false예요'], '최초 관측은 예약이 아닙니다. 잠금 아래에서 다시 검사하므로 이미 다른 작업이 썼다면 가져갈 표시가 없어요. 처음 본 값만 믿지 않는 이유입니다.'), ('try_wait_for_completion은 표시가 없으면 대기 항목을 줄에 남기나요?', ['아니요. 이번 소비를 시도하고 결과를 돌려줘요', '네. 나중 알림을 받으려고 반드시 항목을 등록해요'], '이 함수에는 대기 등록이나 schedule 경로가 없습니다. 잠금 아래 재검사와 표시 소비는 있지만, 완료가 올 때까지 줄에 서서 기다리는 함수는 아니에요.')]), 'os1519': ('도장이 보인다고 확인하는 것과 도장 하나를 내 몫으로 가져가는 것은 다릅니다. 내가 “있다”고 본 뒤 다른 친구가 가져가면, 내 대답은 참이어도 현재 상자는 비어 있을 수 있습니다.', 'completion_done의 관측 결과를 표시 소비나 사용자 종료와 구별합니다.', 'A가 done=1 관측 → B가 소비해 0 → A가 잠금 잡았다 풀기 → true를 그리세요. 같은 순서의 try_wait 결과 false와 비교하세요.', ['completion_done은 먼저 READ_ONCE(done)을 봅니다. 0이면 false로 돌아갑니다. 여기서 보는 것은 완료 표시이며 대기 줄의 사람 수가 아닙니다. 줄이 비었어도 아직 완료 표시가 없으면 false일 수 있습니다.', '0이 아닌 값을 보면 raw 잠금을 한 번 잡았다가 풀고 true를 반환합니다. try_wait와 달리 잠금 안에서 done을 다시 확인하는 if가 없습니다. done--로 표시를 소비하는 명령도 없습니다.', '왜 잠금을 한 번 거칠까요? complete가 표시를 남겼지만 아직 같은 잠금 안에서 completion 자료를 다루고 있을 수 있기 때문입니다. 그 잠금을 잡으려면 앞선 보유자가 풀어야 하므로 진행 중인 그 보호 구간이 끝나는 것을 기다리는 효과가 있습니다.', '그렇다고 모든 사용자나 미래 호출까지 종료되었다는 뜻은 아닙니다. 예를 들어 A가 1을 읽고 B가 그 표시를 소비해 0으로 만든 뒤 A가 잠금을 잡았다 풀면, A는 true를 돌려주지만 done은 0일 수 있습니다. 잠금 아래 재검사가 없는 실제 순서 때문에 가능한 경우입니다.', 'complete_all로 UINT_MAX가 유지되는 동안에는 true가 나옵니다. 하지만 깨어난 작업들이 아직 후속 일을 하는 중일 수 있습니다. true를 보고 대기 줄이 비었다거나 모든 작업이 끝났다고 판단하면 안 됩니다.', '원문 주석의 waiter 표현만 떼어 외우지 말고 본문이 무엇을 읽는지 확인하세요. 이 함수는 task_list를 세지 않습니다. 표시를 지금 소비하려면 try_wait의 계약을, 자료를 안전하게 없애려면 다른 사용자 종료를 보장하는 전체 규칙을 확인해야 합니다.'], [('completion_done이 true면 대기 줄이 반드시 비어 있나요?', ['네. 줄의 길이를 직접 세어 0임을 보장해요', '아니요. 완료 표시 관측과 대기 항목 수는 달라요'], '본문은 done을 읽으며 task_list의 길이는 보지 않습니다. complete_all 뒤에도 사용자들이 정리 중일 수 있어요. 완료 표시가 있다는 관측을 사람 수 검사로 바꾸어 해석하면 안 됩니다.'), ('completion_done은 잠금 안에서 다시 검사하고 표시 하나를 가져가나요?', ['아니요. 재검사와 소비 명령이 없어요', '네. try_wait_for_completion과 완전히 같아요'], 'try_wait에는 두 번째 검사와 감소가 있지만 이 함수에는 잠금 잡기·풀기 뒤 true 반환만 있습니다. 그 사이 값이 바뀌면 true와 현재 done=0이 함께 가능해요.')]), 'os1520': ('행사 1의 모두 통과 표시를 행사 2에 재사용하려면 먼저 행사 1 참가자들이 사용을 끝냈는지 알아야 합니다. “모두 이름을 불렀다”는 것과 “모두 나갔다”는 것은 다른 시점입니다.', '완료 표시의 재설정과 이전 사용자 종료를 서로 다른 단계로 이해합니다.', '행사 1 완료 통지 → 이전 사용자 모두 종료 확인 → reinit으로 0 → 행사 2 시작을 그리세요. 너무 이른 reinit이 어느 화살표를 건너뛰는지 표시하세요.', ['complete_all은 done을 UINT_MAX로 만들어 재설정 전까지 계속 완료된 상태로 둡니다. 현재 줄의 대기자뿐 아니라 나중에 기다리는 쪽도 이 표시로 통과할 수 있습니다. 한 번 통과할 때마다 줄어드는 일반 완료 표시와 다릅니다.', '다음 사건에도 같은 자료를 쓰려면 reinit_completion으로 done을 0으로 돌립니다. 본문은 이 대입 한 줄입니다. 대기자를 기다려 주거나 실행 중인 다른 작업을 멈추거나 이전 완료 통지를 취소하는 명령은 없습니다.', '너무 일찍 0으로 바꾸면 문제가 됩니다. A를 깨워 놓았지만 A가 아직 완료 표시를 확인하기 전이라고 해 봅시다. 다른 쪽이 먼저 표시를 지우면 A는 표시가 없다고 보고 다시 기다릴 수 있습니다. 다음 사건의 알림을 이전 사건의 대기자가 사용하게 되는 식의 혼동도 막아야 합니다.', '따라서 원문은 complete_all 뒤 모든 대기자가 깨어나 사용을 마친 뒤 재초기화하도록 요구합니다. completion_done은 그런 인원 점검 함수가 아닙니다. 완료 표시가 유지되는 동안 true라고 해서 각 사용자가 끝났다는 증거가 되지 않습니다.', '숫자가 최대값에서 더 증가하지 않고 유지되는 것은 넘침을 막는 규칙입니다. complete_all을 여러 번 불러도 그 숫자가 유지된다는 사실만으로 사건을 올바른 순서로 처리했다고 증명할 수 없습니다. 숫자 계산의 안전성과 사건 구분은 별도 문제입니다.', '시간 초과나 신호 때문에 기다리는 쪽이 먼저 돌아와도 나중에 complete할 다른 작업이 남을 수 있습니다. 재사용이나 해제 전에 그런 사용까지 정리해야 합니다. 이전 사건의 종료 확인, 표시 재설정, 다음 작업 시작을 누가 책임지는지 정해 두어야 같은 자료를 안전하게 다시 쓸 수 있습니다.'], [('complete_all을 부르자마자 아무 확인 없이 reinit해도 언제나 안전한가요?', ['네. 깨움 호출이 모든 후속 작업까지 끝내요', '아니요. 이전 사용자들이 사용을 마쳤는지 보장해야 해요'], '깨워도 그 작업이 아직 실행되거나 정리되지 않았을 수 있습니다. reinit은 done을 0으로 바꿀 뿐 종료를 기다리지 않아요. 먼저 이전 사용 종료를 확인해야 합니다.'), ('최대값이 반복 알림에도 0으로 넘치지 않으면 재사용 순서와 수명 문제도 모두 해결되나요?', ['아니요. 사건 주기와 사용자 종료 규칙도 필요해요', '네. 숫자가 유지되면 모든 경쟁이 사라져요'], '포화 처리는 숫자 넘침을 막습니다. 하지만 누가 어느 사건을 기다리는지, 누가 아직 자료에 접근하는지는 관리하지 않아요. 안전한 재설정 시점과 사용 종료 규칙이 따로 필요합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_375.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
